window.ardaEmblem=function(key,size){var h=window.ARDA_HERALD[key];if(!h)return"";
 var s=size||40;
 if(h.file){return '<img src="'+h.file+'" width="'+s+'" height="'+Math.round(s*1.2)+'" loading="lazy" style="object-fit:contain;vertical-align:middle" alt="'+h.blazon.replace(/"/g,"")+'">';}
 if(h.forge&&window.ardaForgeDevice)return window.ardaForgeDevice(h.forge,s);
 return '<svg width="'+s+'" height="'+Math.round(s*1.2)+'" viewBox="0 0 40 48" style="vertical-align:middle"><use href="#em-'+key+'"/></svg>';};
window.ardaEmblemNote=function(key){var h=window.ARDA_HERALD[key];if(!h)return"";
 var BB={artwork:["#e9f3e4","#7aa86a","✔ Tolkien's device"],design:["#e6eef7","#6f8cae","✦ Tolkien's design, drawn here"],
         text:["#f2ecf7","#9a7ab5","✧ blazoned in the texts"],inferred:["#fdf3df","#d0a53c","◆ interpretive"],
         silent:["#efe8d6","#a89b80","◌ no device recorded"]};
 var q=BB[h.basis||(h.canon?"artwork":"inferred")];
 var tag='<span style="background:'+q[0]+';border:1px solid '+q[1]+';border-radius:8px;padding:0 6px;font-size:9.5px">'+q[2]+'</span>';
 var attr=h.canon?('recreation via <a href="'+h.src+'" target="_blank" style="color:#7a4a12">Wikimedia Commons</a>, '+h.license):('lore-derived '+h.author);
 return '<div style="font-size:11px;margin-top:3px">'+tag+' <span class="cite">'+h.blazon+'</span><br><span class="cite" style="font-size:10px">'+attr+'</span></div>';};

window.ARDA_HERALD_ALIAS={mordor:"redeye"};
window.ardaSwapEmblems=function(sv,NS){var defs=sv.querySelector("defs");if(!defs)return;
 var doOne=function(symId,key){var h=window.ARDA_HERALD[key];if(!h||!h.file)return;
  var sym=document.getElementById(symId);if(!sym){sym=document.createElementNS(NS,"symbol");sym.id=symId;sym.setAttribute("viewBox","0 0 40 48");defs.appendChild(sym);}
  sym.innerHTML='<image href="'+h.file+'" x="0" y="0" width="40" height="48" preserveAspectRatio="xMidYMid meet"/>';};
 Object.keys(window.ARDA_HERALD).forEach(function(k){doOne("em-"+k,k);});
 Object.keys(window.ARDA_HERALD_ALIAS).forEach(function(a){doOne("em-"+a,window.ARDA_HERALD_ALIAS[a]);});};
window.ardaHeraldCredits=function(){var seen={},rows=[];
 Object.keys(window.ARDA_HERALD).forEach(function(k){var h=window.ARDA_HERALD[k];if(!h.canon||seen[h.src])return;seen[h.src]=1;
  rows.push('<a href="'+h.src+'" target="_blank" style="color:#7a4a12">'+h.label+'</a> — '+h.license+(h.author&&h.author!=='?'?' · '+h.author:''));});
 return '<b>Heraldry credits.</b> Canonical devices are recreations of Tolkien\'s designs from Wikimedia Commons, reused under their licenses (CC BY-SA / Public Domain) with attribution. Interpretive devices (Durin\'s Folk, Fingolfin) are the archive\'s own lore-derived reconstructions, tagged as such.<br><span class="cite" style="font-size:10px">'+rows.join(' · ')+'</span>';};

window.ardaSwapAllEmblems=function(){var NS="http://www.w3.org/2000/svg";var anyDefs=document.querySelector("defs");
 function set(symKey,srcKey){var h=window.ARDA_HERALD[srcKey||symKey];if(!h)return;if(!h.file&&!h.forge)return;
  var sym=document.getElementById("em-"+symKey);
  if(!sym){if(!anyDefs)return;sym=document.createElementNS(NS,"symbol");sym.id="em-"+symKey;anyDefs.appendChild(sym);}
  if(sym.getAttribute("data-canon"))return; sym.setAttribute("data-canon","1");
  if(h.file){sym.setAttribute("viewBox","0 0 40 48");sym.innerHTML='<image href="'+h.file+'" x="0" y="0" width="40" height="48" preserveAspectRatio="xMidYMid meet"/>';}
  else if(h.forge&&window.ardaForgeInner){sym.setAttribute("viewBox","0 0 200 226");sym.innerHTML=window.ardaForgeInner(h.forge);}}
 Object.keys(window.ARDA_HERALD).forEach(function(k){set(k);});
 Object.keys(window.ARDA_HERALD_ALIAS).forEach(function(a){set(a,window.ARDA_HERALD_ALIAS[a]);});};
if(document.readyState!=="loading")window.ardaSwapAllEmblems();
else document.addEventListener("DOMContentLoaded",window.ardaSwapAllEmblems);


/* ---- reusable device forge (original art, by Tolkien's Elvish rules) ---- */
// ===== the Device Forge engine =====
// Original SVG generator. Follows the rules Tolkien set down for Elvish heraldry
// (shape by bearer, rank by rim-points, radial symmetry) as recorded in his own note
// quoted in Hammond & Scull and in Zurek, 'Heraldry in J.R.R. Tolkien's Legendarium',
// The Coat of Arms 4th ser. 5 (2022), 145-182. No artwork is copied; the shapes are drawn
// from arithmetic here.
// A square device on the plates fills its panel almost edge to edge; 0.84 left a
// margin the paintings do not have. One constant so the four places cannot drift apart.
var ARDA_SQ=0.94;
var ARDA_GRAD_N=0;   // unique ids for the gradients a course may ask for
// Measured off every plate: Tolkien's lozenge is a SQUARE standing on its point --
// the ink box of all thirteen lozenge plates is exactly 1.00 wide for 1.00 tall, where
// the forge had been drawing 0.82.  His Gondolin shields are 0.50 -- twice as tall as
// wide -- where the forge drew 0.75.  Both are corrected here, once.
var ARDA_LZ=1.00;      // lozenge half-width as a fraction of R
// TOLKIEN'S OWN CONSTRUCTION, taken off the two diagrams of it on Wikimedia Commons
// (Lozenge_four_points.svg and Lozenge_eight_points.svg, Chiswick Chap, CC BY-SA 4.0),
// which draw the lozenge with the circles its points are set against:
//
//   the lozenge is EXACTLY a square on its point            w/h = 1.0000
//   the inner circle is the same whatever the rank          0.266 of the half-diagonal
//   the outer circle grows with the number of points        0.490 for four
//                                                           0.609 for eight
//
// So a device of his has a heart about a quarter of the way out, a ring at about half
// (four points) or three-fifths (eight), and the points running from that ring to the
// rim. A forged device that ignores these sits wrong however well its charges are drawn.
var ARDA_TOL={inner:0.266, outer4:0.490, outer8:0.609};
window.ardaTolkienOuter=function(points){
 // between and beyond the two measured ranks, straight-line in the number of points
 if(!points||points<=4) return ARDA_TOL.outer4;
 if(points>=8) return ARDA_TOL.outer8;
 return ARDA_TOL.outer4+(ARDA_TOL.outer8-ARDA_TOL.outer4)*(points-4)/4;
};
window.ARDA_TOL=ARDA_TOL;
var ARDA_SHW=0.495;    // shield half-width; height stays 0.92R above, 1.06R below
